using System.ComponentModel.DataAnnotations;

namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }

    [Required, StringLength(100)]
    public string Title { get; set; } = string.Empty;

    public string Category { get; set; } = string.Empty;

    [Required, MinLength(1)]
    public string Ingredients { get; set; } = string.Empty;

    [Required, MinLength(1)]
    public string Steps { get; set; } = string.Empty;

    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough
Mozzarella cheese
Fresh basil
San Marzano tomatoes
Olive oil
Salt", Steps = "1. Preheat oven to 475°F
2. Roll out dough into a circle
3. Spread crushed tomatoes on base
4. Add torn mozzarella
5. Bake for 10-12 minutes
6. Top with fresh basil and drizzle olive oil", AverageRating = 4.5, RatingCount = 12 },
        new Recipe { Id = 2, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti
Guanciale or pancetta
Eggs
Pecorino Romano
Black pepper", Steps = "1. Cook pasta in salted water
2. Fry guanciale until crispy
3. Whisk eggs with grated pecorino and pepper
4. Toss hot pasta with guanciale
5. Remove from heat, stir in egg mixture
6. Serve immediately with extra pecorino", AverageRating = 4.8, RatingCount = 20 },
        new Recipe { Id = 3, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken breast
Yogurt
Garam masala
Turmeric
Cumin
Tomato sauce
Heavy cream
Garlic
Ginger", Steps = "1. Marinate chicken in yogurt and spices for 2 hours
2. Grill or bake chicken until charred
3. Sauté garlic and ginger in oil
4. Add tomato sauce and spices
5. Simmer, then add cream
6. Add chicken pieces and cook 10 minutes", AverageRating = 4.6, RatingCount = 15 },
        new Recipe { Id = 4, Title = "Vegetable Pad Thai", Category = "Thai", Ingredients = "Rice noodles
Tofu
Bean sprouts
Peanuts
Lime
Tamarind paste
Fish sauce
Sugar
Garlic
Eggs", Steps = "1. Soak rice noodles in warm water
2. Make sauce: mix tamarind, fish sauce, sugar
3. Fry tofu until golden
4. Scramble eggs in wok
5. Add noodles and sauce
6. Toss with bean sprouts, top with peanuts and lime", AverageRating = 4.3, RatingCount = 8 },
        new Recipe { Id = 5, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef
Taco seasoning
Corn tortillas
Lettuce
Tomato
Cheddar cheese
Sour cream
Salsa", Steps = "1. Brown ground beef in a skillet
2. Add taco seasoning and water
3. Simmer until thickened
4. Warm tortillas
5. Assemble with meat, lettuce, tomato, cheese
6. Top with sour cream and salsa", AverageRating = 4.1, RatingCount = 10 },
        new Recipe { Id = 6, Title = "Miso Ramen", Category = "Japanese", Ingredients = "Ramen noodles
Miso paste
Chicken broth
Soy sauce
Soft-boiled egg
Chashu pork
Green onions
Corn
Nori", Steps = "1. Heat broth and dissolve miso paste
2. Season with soy sauce and mirin
3. Cook ramen noodles separately
4. Slice chashu pork
5. Assemble bowl: noodles, broth, toppings
6. Garnish with green onions and nori", AverageRating = 4.7, RatingCount = 18 },
    };

    private int _nextId = 7;

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
    }

    public IReadOnlyList<Recipe> GetRecipesByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetRecipeById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
        recipe.RatingCount++;
        recipe.AverageRating = Math.Round(totalStars / recipe.RatingCount, 1);
    }
}

@rendermode InteractiveServer
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= _displayStars ? "filled" : "")"
              @onclick="() => Rate(star)"
              @onmouseover="() => _displayStars = star"
              @onmouseout="() => _displayStars = (int)Math.Round(_currentAverage)">
            ★
        </span>
    }
    <span class="rating-info">@_currentAverage.ToString("0.0") (@_ratingCount ratings)</span>
    @if (_submitted)
    {
        <span class="text-success ms-2">Thanks for rating!</span>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public int RecipeId { get; set; }

    [Parameter]
    public double InitialAverage { get; set; }

    [Parameter]
    public int InitialCount { get; set; }

    private int _displayStars;
    private double _currentAverage;
    private int _ratingCount;
    private bool _submitted;

    protected override void OnParametersSet()
    {
        _currentAverage = InitialAverage;
        _ratingCount = InitialCount;
        _displayStars = (int)Math.Round(_currentAverage);
    }

    private void Rate(int stars)
    {
        RecipeService.AddRating(RecipeId, stars);
        var recipe = RecipeService.GetRecipeById(RecipeId);
        if (recipe is not null)
        {
            _currentAverage = recipe.AverageRating;
            _ratingCount = recipe.RatingCount;
            _displayStars = stars;
        }
        _submitted = true;
    }
}

.star-rating {
    display: inline-flex;
    align-items: center;
    gap: 2px;
}

.star {
    font-size: 1.5rem;
    cursor: pointer;
    color: #ccc;
    transition: color 0.15s;
}

.star.filled {
    color: #f5a623;
}

.star:hover {
    color: #f5a623;
}

.rating-info {
    margin-left: 0.5rem;
    font-size: 0.9rem;
    color: #666;
}

