toolArgs.file_text:
@rendermode InteractiveServer
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= _displayStars ? "filled" : "")"
              @onclick="() => Rate(star)"
              @onmouseover="() => _displayStars = star"
              @onmouseout="() => _displayStars = (int)Math.Round(_currentAverage)">
            ★
        </span>
    }
    <span class="rating-info">@_currentAverage.ToString("0.0") (@_ratingCount ratings)</span>
    @if (_submitted)
    {
        <span class="text-success ms-2">Thanks for rating!</span>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public int RecipeId { get; set; }

    [Parameter]
    public double InitialAverage { get; set; }

    [Parameter]
    public int InitialCount { get; set; }

    private int _displayStars;
    private double _currentAverage;
    private int _ratingCount;
    private bool _submitted;

    protected override void OnParametersSet()
    {
        _currentAverage = InitialAverage;
        _ratingCount = InitialCount;
        _displayStars = (int)Math.Round(_currentAverage);
    }

    private void Rate(int stars)
    {
        RecipeService.AddRating(RecipeId, stars);
        var recipe = RecipeService.GetRecipeById(RecipeId);
        if (recipe is not null)
        {
            _currentAverage = recipe.AverageRating;
            _ratingCount = recipe.RatingCount;
            _displayStars = stars;
        }
        _submitted = true;
    }
}

